import{G as e,K as t,n,ot as r}from"./chunks/framework.BZpZOnGD.js";var i=JSON.parse(`{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"documentalist-lab/generate-sample-content/index.md","filePath":"documentalist-lab/generate-sample-content/index.md"}`),a={name:`documentalist-lab/generate-sample-content/index.md`};function o(n,i,a,o,s,c){return r(),e(`div`,null,[...i[0]||=[t(`<h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to “Overview”">​</a></h2><div class="tip custom-block"><p class="custom-block-title">NOTE</p><p>This lab is designed to run safely in parallel with other participants. To avoid conflicts in the shared repository, <strong>every participant works in their own namespace</strong> based on their last name.</p></div><p>In this lab you will be asked for your last name. This will be used to:</p><table tabindex="0"><thead><tr><th>What</th><th>How</th></tr></thead><tbody><tr><td><strong>Namespace your files</strong></td><td>Local files go to <code>HR_&lt;YOUR_LASTNAME&gt;/</code></td></tr><tr><td><strong>Create a namespaces in the repository</strong></td><td>Documents are filed under <code>/BOB_LAB/&lt;YOUR_LASTNAME&gt;/</code></td></tr><tr><td><strong>Generate unique employees</strong></td><td>Your 5 employees are deterministically generated from your name</td></tr><tr><td><strong>Prefix employee IDs</strong></td><td>IDs become <code>YOU001</code>–<code>YOU005</code> (first 3 letters of your last name)</td></tr></tbody></table><h3 id="the-hr-document-taxonomy" tabindex="-1">The HR Document Taxonomy <a class="header-anchor" href="#the-hr-document-taxonomy" aria-label="Permalink to “The HR Document Taxonomy”">​</a></h3><p>Before generating content, understand the 8 HR document categories:</p><table tabindex="0"><thead><tr><th>#</th><th>Category</th><th>Document Types</th></tr></thead><tbody><tr><td>1</td><td><strong>Recruitment</strong></td><td>Job Application, Interview Notes</td></tr><tr><td>2</td><td><strong>Employment Contract</strong></td><td>Employment Contract</td></tr><tr><td>3</td><td><strong>Personal Administration</strong></td><td>ID Documents, Personal Info</td></tr><tr><td>4</td><td><strong>Payroll</strong></td><td>Payslip, Salary Info</td></tr><tr><td>5</td><td><strong>Performance</strong></td><td>Performance Review</td></tr><tr><td>6</td><td><strong>Training</strong></td><td>Training Record</td></tr><tr><td>7</td><td><strong>Disciplinary</strong></td><td>Disciplinary Record</td></tr><tr><td>8</td><td><strong>Exit</strong></td><td>Exit Notes</td></tr></tbody></table><p><strong>5</strong> employees × <strong>11</strong> documents each = <strong>55</strong> documents <strong>total</strong></p><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to “Prerequisites”">​</a></h2><ul><li>Completed the previous lab: <em>Meet Bob, your AI documentalist</em>.</li><li>Access to IBM Content Navigator (link is in the Box note provided to you by the lab facilitators).</li><li>Python 3.13+ for running the document generation script and the scripts needed by the skills.</li></ul><h2 id="lab-sections" tabindex="-1">Lab Sections <a class="header-anchor" href="#lab-sections" aria-label="Permalink to “Lab Sections”">​</a></h2><p>This lab is divided into 6 sections:</p><ul><li><strong>Generate Sample Documents</strong> - Run the script to create your personal document set</li><li><strong>Understand Document Properties</strong> - Learn which metadata to set on HR documents</li><li><strong>Upload First Employee</strong> - Upload documents for your first employee</li><li><strong>Upload Remaining Employees</strong> - Batch upload the rest</li><li><strong>Verify Documents</strong> - Check that documents were created correctly</li><li><strong>Review in Navigator</strong> - Browse your documents in the web interface</li></ul><p>Ready to begin? Click the <em>&quot;Generate Sample Documents&quot;</em> link below to get started.</p>`,14)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};